contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(uint256 amount) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.go{value: amount}();
        assert(address(c).balance == 0);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        bool reverted;
        try c.go{value: amount}() { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}
